{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.INVENTORY_RECONCILIATION_RAW AS WITH excluded_skus AS ( SELECT DISTINCT UPPER(TRIM(\"Item SkuCode\")) AS sku FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE NULLIF( TRIM(\"Item SkuCode\"), \'\' ) IS NOT NULL AND ( UPPER(TRIM(COALESCE(\"Category Name\", \'\'))) IN ( \'NON- TRADING\', \'NON-TRADING\', \'CARRY BAG\' ) OR UPPER(TRIM(COALESCE(BRAND, \'\'))) = \'GENERAL\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'NT%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'CBB%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'TEST%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'%HANGER%\' OR REGEXP_LIKE( UPPER(TRIM(\"Item SkuCode\")), \'^[0-9]+$\' ) ) ), uc_stock AS ( SELECT CASE WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH1\' THEN 2 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH2\' THEN 8 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-NORTH-TAURU\' THEN 94 END AS branch_code, UPPER(TRIM(u.\"Item SkuCode\")) AS sku, SUM( COALESCE( u.INVENTORY, 0 ) ) AS uc_good_stock, SUM( COALESCE( u.\"Inventory Blocked\", 0 ) ) AS uc_blocked_stock, SUM( COALESCE( u.\"Bad Inventory\", 0 ) ) AS uc_bad_stock, SUM( COALESCE( u.\"Inventory Not Synced\", 0 ) ) AS uc_not_synced_stock, SUM( COALESCE(u.INVENTORY, 0) + COALESCE(u.\"Inventory Blocked\", 0) + COALESCE(u.\"Bad Inventory\", 0) + COALESCE(u.\"Inventory Not Synced\", 0) ) AS uc_stock FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY u WHERE UPPER(TRIM(u.FACILITY)) IN ( \'SAPL-WH1\', \'SAPL-WH2\', \'SAPL-NORTH-TAURU\' ) AND NULLIF( TRIM(u.\"Item SkuCode\"), \'\' ) IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM excluded_skus x WHERE x.sku = UPPER(TRIM(u.\"Item SkuCode\")) ) GROUP BY CASE WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH1\' THEN 2 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH2\' THEN 8 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-NORTH-TAURU\' THEN 94 END, UPPER(TRIM(u.\"Item SkuCode\")) ), logic_date AS ( SELECT MAX(DATE) AS stock_date FROM SNITCH_DB.MAPLEMONK.LOGICERP_WAREHOUSE_GET_STOCK_IN_HAND WHERE BRANCH_CODE IN ( 2, 8, 94 ) ), logic_stock AS ( SELECT l.DATE AS stock_date, l.BRANCH_CODE AS branch_code, MAX(l.BRANCH_NAME) AS logic_warehouse, UPPER(TRIM(l.ADDLITEMCODE)) AS sku, SUM( CASE WHEN UPPER(TRIM(l.GODOWN_NAME)) = \'GOOD_INVENTORY\' THEN COALESCE( l.STOCK_QTY, 0 ) ELSE 0 END ) AS logic_good_stock, SUM( CASE WHEN UPPER(TRIM(l.GODOWN_NAME)) = \'BAD_INVENTORY\' THEN COALESCE( l.STOCK_QTY, 0 ) ELSE 0 END ) AS logic_bad_stock, SUM( CASE WHEN UPPER(TRIM(l.GODOWN_NAME)) IN ( \'GOOD_INVENTORY\', \'BAD_INVENTORY\' ) THEN COALESCE( l.STOCK_QTY, 0 ) ELSE 0 END ) AS logic_stock FROM SNITCH_DB.MAPLEMONK.LOGICERP_WAREHOUSE_GET_STOCK_IN_HAND l CROSS JOIN logic_date d WHERE l.DATE = d.stock_date AND l.BRANCH_CODE IN ( 2, 8, 94 ) AND UPPER(TRIM(l.GODOWN_NAME)) IN ( \'GOOD_INVENTORY\', \'BAD_INVENTORY\' ) AND NULLIF( TRIM(l.ADDLITEMCODE), \'\' ) IS NOT NULL AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'NT%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'CBB%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'TEST%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'%HANGER%\' AND NOT REGEXP_LIKE( UPPER(TRIM(l.ADDLITEMCODE)), \'^[0-9]+$\' ) AND NOT EXISTS ( SELECT 1 FROM excluded_skus x WHERE x.sku = UPPER(TRIM(l.ADDLITEMCODE)) ) GROUP BY l.DATE, l.BRANCH_CODE, UPPER(TRIM(l.ADDLITEMCODE)) ), reco AS ( SELECT d.stock_date, COALESCE( uc.branch_code, logic.branch_code ) AS branch_code, CASE WHEN COALESCE( uc.branch_code, logic.branch_code ) = 2 THEN \'SAPL-WH1\' WHEN COALESCE( uc.branch_code, logic.branch_code ) = 8 THEN \'SAPL-WH2\' WHEN COALESCE( uc.branch_code, logic.branch_code ) = 94 THEN \'SAPL-NORTH-TAURU\' END AS uc_facility, CASE WHEN COALESCE( uc.branch_code, logic.branch_code ) = 2 THEN \'SNITCH - WH - YELHANKA\' WHEN COALESCE( uc.branch_code, logic.branch_code ) = 8 THEN \'SNITCH - WH - YELHANKA 2\' WHEN COALESCE( uc.branch_code, logic.branch_code ) = 94 THEN \'SNITCH - WH - NORTH\' END AS logic_warehouse, COALESCE( uc.sku, logic.sku ) AS sku, COALESCE( uc.uc_good_stock, 0 ) AS uc_good_stock, COALESCE( uc.uc_blocked_stock, 0 ) AS uc_blocked_stock, COALESCE( uc.uc_bad_stock, 0 ) AS uc_bad_stock, COALESCE( uc.uc_not_synced_stock, 0 ) AS uc_not_synced_stock, COALESCE( uc.uc_stock, 0 ) AS uc_stock, COALESCE( logic.logic_good_stock, 0 ) AS logic_good_stock, COALESCE( logic.logic_bad_stock, 0 ) AS logic_bad_stock, COALESCE( logic.logic_stock, 0 ) AS logic_stock, COALESCE( uc.uc_stock, 0 ) - COALESCE( logic.logic_stock, 0 ) AS stock_difference, ABS( COALESCE( uc.uc_stock, 0 ) - COALESCE( logic.logic_stock, 0 ) ) AS absolute_stock_difference, CASE WHEN uc.sku IS NULL THEN \'MISSING_IN_UC\' WHEN logic.sku IS NULL THEN \'MISSING_IN_LOGIC\' WHEN COALESCE(uc.uc_stock, 0) = COALESCE(logic.logic_stock, 0) THEN \'MATCHED\' ELSE \'MISMATCH\' END AS stock_match_status FROM uc_stock uc FULL OUTER JOIN logic_stock logic ON uc.branch_code = logic.branch_code AND uc.sku = logic.sku CROSS JOIN logic_date d ) SELECT stock_date, branch_code, uc_facility, logic_warehouse, sku, uc_good_stock, uc_blocked_stock, uc_bad_stock, uc_not_synced_stock, uc_stock, logic_good_stock, logic_bad_stock, logic_stock, stock_difference, absolute_stock_difference, stock_match_status FROM reco WHERE GREATEST( ABS(uc_stock), ABS(logic_stock) ) > 0 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            